export const html = "<!doctype html>\n<html>\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n    <title>Sidechat</title>\n    <style>\n      * {\n        box-sizing: border-box;\n      }\n      body {\n        margin: 0;\n        font:\n          14px/1.5 system-ui,\n          sans-serif;\n        background: #f6f7f9;\n        color: #202532;\n      }\n      .app {\n        display: grid;\n        grid-template-columns: 220px 1fr;\n        min-height: 100vh;\n      }\n      .side {\n        background: #202a3a;\n        color: #fff;\n        padding: 24px 16px;\n      }\n      .brand {\n        font-size: 22px;\n        font-weight: 750;\n        margin: 0 8px 5px;\n      }\n      .sub {\n        color: #aeb8c7;\n        margin: 0 8px 27px;\n        font-size: 12px;\n      }\n      .side h3 {\n        font-size: 11px;\n        text-transform: uppercase;\n        letter-spacing: 0.1em;\n        color: #aeb8c7;\n        margin: 20px 8px 8px;\n      }\n      .channels {\n        display: grid;\n        gap: 4px;\n      }\n      .channel {\n        border: 0;\n        background: none;\n        color: #c8d0dc;\n        text-align: left;\n        padding: 9px 10px;\n        border-radius: 7px;\n        cursor: pointer;\n        font: inherit;\n      }\n      .channel.active,\n      .channel:hover {\n        background: #354256;\n        color: white;\n      }\n      .main {\n        min-width: 0;\n        display: grid;\n        grid-template-columns: minmax(0, 1fr) 285px;\n        gap: 22px;\n        padding: 28px;\n        max-width: 1400px;\n        width: 100%;\n        margin: auto;\n      }\n      .feed {\n        min-width: 0;\n        display: flex;\n        flex-direction: column;\n        height: calc(100vh - 56px);\n        min-height: 550px;\n        background: #fff;\n        border: 1px solid #e6e8ed;\n        border-radius: 12px;\n        overflow: hidden;\n      }\n      .head {\n        padding: 20px 24px;\n        border-bottom: 1px solid #e9ebef;\n      }\n      .head h1 {\n        font-size: 20px;\n        margin: 0;\n      }\n      .head p {\n        margin: 2px 0 0;\n        color: #777f8c;\n      }\n      .messages {\n        padding: 20px 24px;\n        overflow: auto;\n        flex: 1;\n      }\n      .message {\n        padding: 0 0 18px;\n        margin-bottom: 18px;\n        border-bottom: 1px solid #f0f1f3;\n      }\n      .by {\n        font-weight: 650;\n      }\n      .time {\n        color: #9299a4;\n        font-size: 12px;\n        margin-left: 8px;\n      }\n      .body {\n        white-space: pre-wrap;\n        overflow-wrap: anywhere;\n        margin-top: 4px;\n      }\n      .empty {\n        color: #818895;\n        text-align: center;\n        padding: 45px 10px;\n      }\n      .compose {\n        padding: 16px 20px;\n        border-top: 1px solid #e9ebef;\n      }\n      .row {\n        display: flex;\n        gap: 9px;\n      }\n      input,\n      textarea {\n        font: inherit;\n        border: 1px solid #d9dde4;\n        border-radius: 7px;\n        padding: 10px;\n        width: 100%;\n        background: white;\n        color: inherit;\n      }\n      textarea {\n        resize: vertical;\n        min-height: 68px;\n      }\n      .compose textarea {\n        flex: 1;\n      }\n      .compose .row {\n        align-items: flex-end;\n      }\n      button.primary {\n        background: #485fd7;\n        color: #fff;\n        border: 0;\n        border-radius: 7px;\n        padding: 10px 15px;\n        font: inherit;\n        font-weight: 600;\n        cursor: pointer;\n      }\n      button.primary:hover {\n        background: #354bbf;\n      }\n      .panel {\n        display: grid;\n        align-content: start;\n        gap: 18px;\n      }\n      .card {\n        background: white;\n        border: 1px solid #e6e8ed;\n        border-radius: 12px;\n        padding: 18px;\n      }\n      .profile-card {\n        color: #202532;\n      }\n      .card h2 {\n        font-size: 15px;\n        margin: 0 0 13px;\n      }\n      .card textarea {\n        min-height: 90px;\n      }\n      .noteSave {\n        margin-top: 9px;\n      }\n      .tasks {\n        display: grid;\n        gap: 10px;\n      }\n      .task {\n        display: flex;\n        gap: 9px;\n        align-items: flex-start;\n      }\n      .task input {\n        width: auto;\n        margin-top: 4px;\n      }\n      .task.done span {\n        text-decoration: line-through;\n        color: #89909b;\n      }\n      .task-add {\n        margin-top: 13px;\n      }\n      .task-add input {\n        margin-bottom: 8px;\n      }\n      .warning {\n        background: #fff7e8;\n        border: 1px solid #f2d8a7;\n        color: #73531b;\n        border-radius: 8px;\n        padding: 10px;\n        font-size: 12px;\n      }\n      .reset {\n        border: 1px solid #d64c4c;\n        background: white;\n        color: #b52e2e;\n        border-radius: 7px;\n        padding: 9px 12px;\n        cursor: pointer;\n        font: inherit;\n      }\n      .status {\n        min-height: 20px;\n        color: #ad3434;\n        font-size: 13px;\n        margin: 8px 0 0;\n      }\n      .arch {\n        color: #7a818c;\n        font-size: 12px;\n        text-align: center;\n      }\n      .loading {\n        padding: 32px;\n        color: #777;\n      }\n      .error {\n        padding: 30px;\n        color: #a22;\n      }\n      @media (max-width: 850px) {\n        .main {\n          grid-template-columns: 1fr;\n          padding: 14px;\n        }\n        .feed {\n          height: 70vh;\n          min-height: 450px;\n        }\n        .panel {\n          grid-template-columns: 1fr 1fr;\n        }\n        .app {\n          grid-template-columns: 160px 1fr;\n        }\n      }\n      @media (max-width: 570px) {\n        .app {\n          display: block;\n        }\n        .side {\n          padding: 13px;\n        }\n        .brand {\n          display: inline-block;\n          margin: 0 12px 0 0;\n        }\n        .sub {\n          display: inline;\n          margin: 0;\n        }\n        .side h3 {\n          display: none;\n        }\n        .channels {\n          display: flex;\n          overflow: auto;\n          margin-top: 10px;\n        }\n        .channel {\n          white-space: nowrap;\n        }\n        .main {\n          padding: 10px;\n        }\n        .panel {\n          grid-template-columns: 1fr;\n        }\n        .feed {\n          min-height: 400px;\n          height: 65vh;\n        }\n        .messages {\n          padding: 16px;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <div id=\"app\" class=\"loading\">Loading workspace…</div>\n    <script>\n      const app = document.querySelector(\"#app\");\n      let state,\n        active = \"general\",\n        busy = false;\n      async function call(path, body) {\n        const r = await fetch(\n          \"/api\" + path,\n          body\n            ? {\n                method: \"POST\",\n                headers: { \"content-type\": \"application/json\" },\n                body: JSON.stringify(body),\n              }\n            : {},\n        );\n        let data;\n        try {\n          data = await r.json();\n        } catch {\n          throw Error(\"Unexpected server response\");\n        }\n        if (!r.ok) throw Error(data.error || \"Request failed\");\n        return data;\n      }\n      function esc(s) {\n        return String(s).replace(\n          /[&<>\"']/g,\n          (c) =>\n            ({\n              \"&\": \"&amp;\",\n              \"<\": \"&lt;\",\n              \">\": \"&gt;\",\n              '\"': \"&quot;\",\n              \"'\": \"&#39;\",\n            })[c],\n        );\n      }\n      function render() {\n        if (!state) return;\n        const ch =\n          state.channels.find((x) => x.id === active) || state.channels[0];\n        active = ch.id;\n        app.className = \"app\";\n        app.innerHTML =\n          '<aside class=\"side\"><div class=\"brand\">' +\n          esc(state.title) +\n          '</div><p class=\"sub\">Demo workspace</p><button type=\"button\" class=\"channel profile-toggle\">👤 Profile · @' +\n          esc(state.currentSlug) +\n          '</button><section class=\"card profile-card\" hidden><h2>Your profile</h2><div>' +\n          esc(state.currentUser) +\n          \" · @\" +\n          esc(state.currentSlug) +\n          '</div><form class=\"profile-form\" style=\"margin-top:10px\"><input name=\"slug\" value=\"' +\n          esc(state.currentSlug) +\n          '\" maxlength=\"30\" required><button class=\"primary\" style=\"margin-top:8px\">Save slug</button></form><button type=\"button\" class=\"reset logout\" style=\"margin-top:8px\">Log out</button><p class=\"status\" id=\"profile-status\"></p></section><h3>Channels</h3><nav class=\"channels\">' +\n          state.channels\n            .map(\n              (c) =>\n                '<button class=\"channel ' +\n                (c.id === active ? \"active\" : \"\") +\n                '\" data-channel=\"' +\n                esc(c.id) +\n                '\"># ' +\n                esc(c.name) +\n                \"</button>\",\n            )\n            .join(\"\") +\n          '</nav></aside><main class=\"main\"><section class=\"feed\"><header class=\"head\"><h1># ' +\n          esc(ch.name) +\n          '</h1><p>Messages from your team</p></header><div class=\"messages\">' +\n          (state.messages.some((m) => m.channel === active)\n            ? state.messages\n                .filter((m) => m.channel === active)\n                .map(\n                  (m) =>\n                    '<article class=\"message\"><span class=\"by\">' +\n                    esc(m.user) +\n                    '</span><time class=\"time\">' +\n                    new Date(m.created_at).toLocaleString() +\n                    '</time><div class=\"body\">' +\n                    esc(m.body) +\n                    \"</div></article>\",\n                )\n                .join(\"\")\n            : '<div class=\"empty\">No messages yet. Start the conversation.</div>') +\n          '</div><form class=\"compose\"><div class=\"row\"><textarea name=\"message\" maxlength=\"2000\" placeholder=\"Message #' +\n          esc(ch.name) +\n          '…\" required></textarea><button class=\"primary\">Send</button></div><div style=\"color:#818895;font-size:12px;margin-top:7px\">Posting as ' +\n          esc(state.currentUser) +\n          '</div><p class=\"status\" id=\"message-status\"></p></form></section><aside class=\"panel\"><section class=\"card\"><h2>📌 Pinned note</h2><textarea id=\"note\" maxlength=\"500\">' +\n          esc(ch.note) +\n          '</textarea><button type=\"button\" class=\"primary noteSave\">Save note</button><p class=\"status\" id=\"note-status\"></p></section><section class=\"card\"><h2>✓ Tasks</h2><div class=\"tasks\">' +\n          (state.tasks.length\n            ? state.tasks\n                .map(\n                  (t) =>\n                    '<label class=\"task ' +\n                    (t.completed ? \"done\" : \"\") +\n                    '\"><input type=\"checkbox\" data-task=\"' +\n                    t.id +\n                    '\" ' +\n                    (t.completed ? \"checked\" : \"\") +\n                    \"><span>\" +\n                    esc(t.title) +\n                    \"</span></label>\",\n                )\n                .join(\"\")\n            : '<div class=\"empty\" style=\"padding:10px\">No tasks yet.</div>') +\n          '</div><form class=\"task-add\"><input name=\"task\" maxlength=\"160\" placeholder=\"Add a task…\" required><button class=\"primary\">Add task</button><p class=\"status\" id=\"task-status\"></p></form></section><div class=\"warning\"><strong>Destructive action:</strong> reset permanently replaces workspace content with the original sample data.<br><button class=\"reset\" style=\"margin-top:9px\">Reset to seed</button></div>' +\n          (state.isAdmin\n            ? '<section class=\"card\"><h2>Admin · users</h2><div class=\"tasks\">' +\n                (state.users || [])\n                  .map(\n                    (u) =>\n                      '<div style=\"border-top:1px solid #eee;padding:9px 0\"><strong>' +\n                      esc(u.email) +\n                      '</strong><div style=\"font-size:12px;color:#778\">@' +\n                      esc(u.slug) +\n                      \" · \" +\n                      (u.approved ? \"approved\" : \"pending\") +\n                      (u.must_reset ? \" · reset required\" : \"\") +\n                      '</div><div class=\"row\" style=\"margin-top:7px\">' +\n                      (!u.approved\n                        ? '<button class=\"primary admin-action\" data-action=\"approve\" data-email=\"' +\n                          esc(u.email) +\n                          '\">Approve</button>'\n                        : '<button class=\"reset admin-action\" data-action=\"revoke\" data-email=\"' +\n                          esc(u.email) +\n                          '\">Revoke</button>') +\n                      '<button class=\"reset admin-action\" data-action=\"reset-password\" data-email=\"' +\n                      esc(u.email) +\n                      '\">Reset password</button></div></div>',\n                  )\n                  .join(\"\") ||\n              \"<p>No accounts.</p>\" +\n                '</div><p class=\"status\" id=\"admin-status\"></p></section>'\n            : \"\") +\n          '<div class=\"arch\">One Worker + one Durable Object; state lives in this object.</div></aside></main>';\n        const messages = app.querySelector(\".messages\");\n        messages.scrollTop = messages.scrollHeight;\n      }\n      async function act(fn, status) {\n        if (busy) return;\n        busy = true;\n        if (status) status.textContent = \"\";\n        try {\n          await fn();\n          await refresh();\n        } catch (e) {\n          if (status) status.textContent = e.message;\n          else alert(e.message);\n        } finally {\n          busy = false;\n        }\n      }\n      async function refresh() {\n        try {\n          state = await call(\"/state\");\n          render();\n        } catch (e) {\n          if (\n            e.message === \"Please log in\" ||\n            e.message === \"Password reset required\"\n          ) {\n            app.className = \"auth\";\n            app.innerHTML =\n              '<main style=\"max-width:420px;margin:12vh auto;background:white;padding:28px;border-radius:12px\"><h1>Sidechat</h1><p id=\"auth-status\">' +\n              esc(e.message) +\n              '</p><form id=\"login\"><input name=\"email\" type=\"email\" placeholder=\"Email\" required><input name=\"password\" type=\"password\" placeholder=\"Password\" required style=\"margin-top:10px\"><button class=\"primary\" style=\"margin-top:10px\">Log in</button></form><hr><h2>Request an account</h2><form id=\"signup\"><input name=\"email\" type=\"email\" placeholder=\"Email\" required><input name=\"slug\" placeholder=\"User slug\" required style=\"margin-top:8px\"><input name=\"password\" type=\"password\" placeholder=\"Password (8+ characters)\" required style=\"margin-top:8px\"><button class=\"primary\" style=\"margin-top:10px\">Sign up</button></form></main>';\n            return;\n          }\n          throw e;\n        }\n      }\n      app.addEventListener(\"click\", (e) => {\n        if (e.target.closest(\".profile-toggle\")) {\n          const card = app.querySelector(\".profile-card\");\n          card.hidden = !card.hidden;\n        }\n        if (e.target.closest(\".logout\"))\n          act(\n            () =>\n              call(\"/logout\", {}).then(() => {\n                state = null;\n              }),\n            null,\n          );\n        const b = e.target.closest(\"[data-channel]\");\n        if (b) {\n          active = b.dataset.channel;\n          render();\n        }\n        if (e.target.closest(\".noteSave\"))\n          act(\n            () =>\n              call(\"/note\", {\n                channel: active,\n                note: app.querySelector(\"#note\").value,\n              }),\n            app.querySelector(\"#note-status\"),\n          );\n        if (e.target.matches(\".admin-action\")) {\n          const action = e.target.dataset.action,\n            email = e.target.dataset.email;\n          if (\n            action === \"revoke\" &&\n            !confirm(\"Revoke access for \" + email + \"?\")\n          )\n            return;\n          if (\n            action === \"reset-password\" &&\n            !confirm(\n              \"Require \" + email + \" to choose a new password at next login?\",\n            )\n          )\n            return;\n          act(\n            () => call(\"/admin/\" + action, { email }),\n            app.querySelector(\"#admin-status\"),\n          );\n        }\n        if (e.target.matches(\".reset:not(.admin-action)\")) {\n          if (\n            confirm(\n              \"This will permanently delete all messages, notes, and tasks, then restore the seeded sample workspace. Continue?\",\n            )\n          )\n            act(() => call(\"/reset\", {}));\n        }\n      });\n      app.addEventListener(\"keydown\", (e) => {\n        if (\n          e.target.matches(\".compose textarea\") &&\n          e.key === \"Enter\" &&\n          !e.shiftKey\n        ) {\n          e.preventDefault();\n          e.target.closest(\"form\").requestSubmit();\n        }\n      });\n      app.addEventListener(\"submit\", (e) => {\n        const f = e.target;\n        if (f.matches(\".profile-form\")) {\n          e.preventDefault();\n          act(\n            () => call(\"/profile\", { slug: f.slug.value }),\n            app.querySelector(\"#profile-status\"),\n          );\n          return;\n        }\n        if (f.id === \"login\" || f.id === \"signup\") {\n          e.preventDefault();\n          const data = Object.fromEntries(new FormData(f));\n          call(f.id === \"login\" ? \"/login\" : \"/signup\", data)\n            .then(async (d) => {\n              if (f.id === \"signup\") {\n                document.querySelector(\"#auth-status\").textContent = d.message;\n                return;\n              }\n              if (d.must_reset) {\n                const password = prompt(\n                  \"Admin requires you to set a new password (8+ characters):\",\n                );\n                if (!password) throw Error(\"Set your new password to continue\");\n                await call(\"/password\", { password });\n              }\n              await refresh();\n            })\n            .catch((err) => {\n              const s = document.querySelector(\"#auth-status\");\n              if (s) s.textContent = err.message;\n            });\n          return;\n        }\n        e.preventDefault();\n        if (f.matches(\".compose\")) {\n          const status = app.querySelector(\"#message-status\");\n          act(\n            () => call(\"/message\", { channel: active, body: f.message.value }),\n            status,\n          ).then(() => {\n            if (!status.textContent)\n              app.querySelector(\"[name=message]\").value = \"\";\n          });\n        }\n        if (f.matches(\".task-add\"))\n          act(\n            () => call(\"/task\", { title: f.task.value }),\n            app.querySelector(\"#task-status\"),\n          );\n      });\n      app.addEventListener(\"change\", (e) => {\n        if (e.target.matches(\"[data-task]\"))\n          act(() =>\n            call(\"/complete\", {\n              id: Number(e.target.dataset.task),\n              completed: e.target.checked,\n            }),\n          );\n      });\n      refresh().catch((e) => {\n        app.className = \"error\";\n        app.textContent = \"Could not load workspace: \" + e.message;\n      });\n      setInterval(() => {\n        if (!busy && !document.hidden) refresh().catch(() => {});\n      }, 10000);\n    </script>\n  </body>\n</html>\n";
